# Les chemins ci-dessus entourent plusieurs îlots. Retirer le mot logé
# entre les deux feuilles de 36 ; il est le seul à subsister dans sa silhouette.
HOLES = {36:[(749,108),(771,101),(806,96),(850,95),(885,96),(912,91),
             (901,102),(891,115),(880,136),(872,154),(862,174),(853,195),
             (851,207),(826,213),(799,212),(784,207),(779,198),(775,183),
             (778,168),(774,153),(766,143),(759,135),(755,120)]}
def native(point, config):
    x,y=point
    ox,oy=config['origin'];s=config['scale']
    return (round(ox+x/s), round(oy+y/s))

def tile(art, bounds, page, font, number):
    cut = art.crop(art.getbbox())
    top = art.crop((0,0,art.width,max(1,min(art.height,SOURCES[page]['row_end']-bounds[1]))))
    top = top.crop(top.getbbox())
    card = Image.new('RGB',(525,305),'white');d=ImageDraw.Draw(card)
    d.text((10,4),number,fill='#171717',font=font)
    for (x,left,right),obj in zip([(8,7,198),(210,207,515)],[cut,top]):
        # Même résolution pour tous les dessins dans chaque colonne, sauf réduction
        # nécessaire pour tenir dans la case. Le trait témoin indique 200 px natifs.
        maxscale=.34
        scale=min(maxscale,(right-left)/obj.width,230/obj.height)
        resized=obj.resize((max(1,round(obj.width*scale)),max(1,round(obj.height*scale))),Image.Resampling.LANCZOS)
        card.paste(resized,(round((right+left-resized.width)/2),43+(229-resized.height)//2),resized)
        k=round(200*scale)
        d.line((x+3,287,x+3+k,287), fill='#555555',width=2)
    return card

def main():
    source = {pg:Path(n) for pg,n in zip(('89','100'),sys.argv[1:])}
    fonts = ImageFont.truetype('/System/Library/Fonts/Helvetica.ttc',20)
    imgs={pg:Image.open(p).convert('RGB') for pg,p in source.items()}
    arts={};trace={};manifest={}
    for page,c in SOURCES.items():
        assert imgs[page].size==c['dimensions']
        manifest[page]={'oid':c['oid'],'sha256':sha256(source[page].read_bytes()).hexdigest(),'dimensions':c['dimensions'],
                        'url':f"https://collections.library.yale.edu/iiif/2/{c['oid']}/full/full/0/default.jpg"}
    for frag,polygon in POLYGONS.items():
        pg='89' if frag<100 else '100';conf=SOURCES[pg]
        p=[native(v,conf) for v in polygon];holes=[native(v,conf) for v in HOLES.get(frag,[])]
        box=(min(x for x,y in p),min(y for x,y in p),max(x for x,y in p)+1,max(y for x,y in p)+1)
        art=imgs[pg].crop(box).convert('RGBA')
        mask=Image.new('L',art.size); d=ImageDraw.Draw(mask)
        d.polygon([(x-box[0],y-box[1]) for x,y in p],fill=255)
        if holes:d.polygon([(x-box[0],y-box[1]) for x,y in holes],fill=0)
        art.putalpha(mask); arts[frag]=(art,box,pg)
        trace[frag]={'oid':conf['oid'],'boite_native':box,'polygone_natif':p,'exclusion_native':holes}
    key={}
    for nm,model,cands,seed in [('N',36,[140,141,142,143],3640140),('S',140,[33,34,35,36],1400036)]:
        random.Random(seed).shuffle(cands)
        key[nm]={'modele':model,'graine':seed,'codes':dict(zip('ABCD',cands))}
        sheet=Image.new('RGB',(1070,937),'white')
        for tag,frag,(x,y) in zip(['Modèle','A','B','C','D'],[model,*cands],[(273,1),(7,315),(537,315),(7,625),(537,625)]):
            sheet.paste(tile(*arts[frag],fonts,tag),(x,y))
        sheet.save(HERE/f'planche-{nm}.jpg',quality=94)
    (HERE/'reperes.json').write_text(json.dumps({'sources':manifest,'fragments':trace,'planches':key},ensure_ascii=False,indent=1)+'\n')
if __name__=='__main__':
    main()
